import{_ as o,o as t,c as a,a0 as d}from"./chunks/framework.l1I-fhud.js";const p=JSON.parse('{"title":"Concepts","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/concepts.md","filePath":"explanation/concepts.md"}'),s={name:"explanation/concepts.md"};function r(c,e,i,n,l,h){return t(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="concepts" tabindex="-1">Concepts <a class="header-anchor" href="#concepts" aria-label="Permalink to &quot;Concepts&quot;">​</a></h1><p>The vocabulary tamias uses — each term defined once.</p><h2 id="package-and-ref" tabindex="-1">Package and ref <a class="header-anchor" href="#package-and-ref" aria-label="Permalink to &quot;Package and ref&quot;">​</a></h2><ul><li><strong>Package</strong> — <em>bytes + a manifest</em> (<code>tamias.yaml</code>). The manifest names the package (<code>name</code>, <code>version</code>, <code>@scope</code>), its content <code>type</code>, and optional <code>deps:</code>, <code>include:</code>, <code>provider:</code>, and <code>bins[]</code> declarations.</li><li><strong>Ref</strong> — the address of a package source: a local path, a <code>git:</code> clone URL with <code>//subdir</code> and <code>#rev</code>, an <code>http(s):</code> tarball (optionally <code>#sha256:</code>-pinned), a <code>cf:</code> registry ref, or a named-registry <code>&lt;label&gt;:&lt;pkg&gt;@&lt;ver&gt;</code>. See <a href="/tamias/reference/refs.html">Ref grammar</a>.</li><li><strong>Resolved sha</strong> — what a ref pinned to at install time: a commit sha for git, a payload sha256 for tarballs. Recorded on the store entry so provenance survives the ref moving.</li><li><strong>Payload digest</strong> — the content hash of the unpacked payload. <code>tamias verify</code> recomputes it; tampering with the store is detected.</li></ul><h2 id="stores" tabindex="-1">Stores <a class="header-anchor" href="#stores" aria-label="Permalink to &quot;Stores&quot;">​</a></h2><ul><li><strong>Install store</strong> — <code>&lt;tamias-home&gt;/</code> entries of <code>name@version/</code> plus a record (source ref, resolved sha, digest, trust tier). What <code>list</code>, <code>info</code>, <code>verify</code> read.</li><li><strong>Fetch cache</strong> — content-addressed, keyed by resolved sha. Repeat installs and <code>update</code> reuse it; <code>remove</code> never touches it.</li><li><strong>Registry</strong> — where published packages live: a directory (optionally HTTP-served) or a Cloudflare Worker + R2/D1/KV. <code>publish</code>/<code>search</code> talk to it; installs read its <code>index.json</code>.</li><li><strong>Bin dir</strong> — where a package&#39;s executable surfaces land: <code>$TAMIAS_BIN_DIR</code> → <code>$XDG_BIN_HOME</code> → <code>~/.local/bin</code>.</li></ul><h2 id="content-types-and-drivers" tabindex="-1">Content types and drivers <a class="header-anchor" href="#content-types-and-drivers" aria-label="Permalink to &quot;Content types and drivers&quot;">​</a></h2><ul><li><strong>Content type</strong> (<code>type:</code>/<code>kind</code>) — the <em>meaning</em> of a payload, declared as data in the manifest. The engine never links product code.</li><li><strong>Driver</strong> (<code>tamias-driver-&lt;type&gt;</code>) — the subprocess that knows how a type installs/deploys/uninstalls. Discovered on <code>PATH</code> or in <code>&lt;tamias-home&gt;/drivers/</code>; fails closed when absent.</li><li><strong>Bundled driver</strong> — a <code>drivers/</code> dir inside the payload. Arbitrary code → gated by <code>--allow-drivers</code> / consent memory.</li><li><strong>Provider</strong> — the manifest&#39;s declarative <code>provider:</code> block: services, ingress, verbs. <code>tamias deploy</code> renders it into per-user service units (systemd / launchd / Task Scheduler) without a driver.</li><li><strong><code>bins[]</code></strong> — declared executable surfaces: <code>shim: cli</code> (a generated script dispatching <code>tamias bin exec</code> → the kind driver) or <code>payload: tools/bin/&lt;triple&gt;/…</code> (a real binary, linked through a per-package <code>bin-alias</code> so upgrades don&#39;t dangle).</li></ul><h2 id="trust" tabindex="-1">Trust <a class="header-anchor" href="#trust" aria-label="Permalink to &quot;Trust&quot;">​</a></h2><ul><li><strong>Trust tier</strong> — <code>official</code> / <code>signed</code> / <code>pinned</code> / <code>unpinned</code> / <code>bad</code>, <em>computed</em> at install/verify time from the ref&#39;s pin, the package signature, and your signers files. Never self-declared.</li><li><strong>Signers files</strong> — <code>allowed_signers</code> (&quot;may sign packages I install&quot;) vs <code>official_signers</code> (the smaller curated set earning the <code>official</code> badge); <code>ssh-keygen -Y</code> format, namespace <code>tamias-package</code>.</li><li><strong>Consent</strong> — the <code>--allow-drivers</code> gate, remembered per payload digest in <code>~/.config/tamias/consented.json</code>. Binds to exact bytes, not the package name.</li><li><strong><code>include:</code></strong> — manifest composition: entries resolve to store payloads or recursively-installed refs; the <em>composed</em> tree is what drivers see, what gets digested, and what the store commits.</li></ul>',10)])])}const m=o(s,[["render",r]]);export{p as __pageData,m as default};
